          var unicode = this.source.slice(this.index, this.index + 4);
          if (!/^[0-9a-fA-F]{4}$/.test(unicode)) this.fail('invalid unicode escape');
          result += String.fromCharCode(parseInt(unicode, 16));
          this.index += 4;
